const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const TARGET=process.env.TARGET_FILE,SHA=process.env.TARGET_SHA,BLOB=process.env.TARGET_BLOB;const assert=(x,m)=>{if(!x)throw new Error(m)},sh=c=>cp.execSync(c,{encoding:'utf8'}).trim();
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[];}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t];}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context});}}depth+=o-c;while(stack.length&&depth<=stack[stack.length-1].depthBefore){const p=stack.pop();if(p.type==='rule')sel=null;}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d);}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)};}
assert(sh('git rev-parse HEAD')===SHA,'wrong parent SHA');assert(sh(`git hash-object ${TARGET}`)===BLOB,'parent blob drift');const src=fs.readFileSync(TARGET,'utf8'),p=parse(src);assert(p.declarations.length===754&&p.dead.length===27,`parent parse drift ${p.declarations.length}/${p.dead.length}`);const families=new Set(p.dead.map(d=>d.selector));assert(families.size===8,`family drift ${families.size}`);const contexts={global:0,max1023:0,min1024:0};for(const d of p.dead){assert(!d.important&&!d.winnerImportant,`important drift ${d.line}`);assert(d.winnerLine>d.line,`winner order ${d.line}`);if(d.context==='')contexts.global++;else if(d.context==='@media (max-width: 1023px)')contexts.max1023++;else if(d.context==='@media (min-width: 1024px)')contexts.min1024++;else throw new Error(`context drift ${d.context}`);}assert(contexts.global===15&&contexts.max1023===4&&contexts.min1024===8,`context counts ${JSON.stringify(contexts)}`);const identical=p.dead.filter(d=>d.value===d.winnerValue&&d.important===d.winnerImportant).length;assert(identical===13&&p.dead.length-identical===14,`winner identity drift ${identical}/${p.dead.length-identical}`);const expectedLines='40,41,42,43,48,49,50,51,52,53,54,58,705,706,710,711,822,981,982,1001,1102,1103,1104,1105,1110,1111,1115';assert(p.dead.map(d=>d.line).join(',')===expectedLines,`dead lines drift ${p.dead.map(d=>d.line).join(',')}`);const finalNewline=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(finalNewline&&lines.at(-1)==='')lines.pop();for(const d of [...p.dead].sort((a,b)=>b.line-a.line)){assert(lines[d.line-1]?.trim().startsWith(`${d.property}:`),`line mismatch ${d.line}`);lines.splice(d.line-1,1);}fs.writeFileSync(TARGET,lines.join('\n')+(finalNewline?'\n':''));const after=parse(fs.readFileSync(TARGET,'utf8'));assert(after.declarations.length===727&&after.dead.length===0,`candidate drift ${after.declarations.length}/${after.dead.length}`);const stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/);assert(stat[0]==='0'&&stat[1]==='27'&&stat[2]===TARGET,`diff drift ${stat.join(' ')}`);const buf=fs.readFileSync(TARGET),hash=crypto.createHash('sha256').update(buf).digest('hex');console.log(`CANDIDATE BUILD PASS|decl=754->727|dead=27->0|families=8|identical=13|changed=14|additions=0|deletions=27|hash=${hash}|bytes=${buf.length}`);
